"""Bilingual, table-first view of fixed lexical 1.1 aggregates."""
from html import escape as e
import json
FILES=['media-subject-linkage.csv','media-lexical-quarterly.csv','lexical-extensions.json','lexical-extensions-manifest.json']
def section(d,lang,table):
    hr=lang=='hr';t=lambda en,cr:cr if hr else en
    n=lambda x:f'{x:,.0f}'.replace(',','.') if hr else f'{x:,.0f}'
    pct=lambda x:f'{100*x:.1f}'.replace('.',',')+'%' if hr else f'{100*x:.1f}%'
    rows=[(e(r['label_'+lang]),n(r['whole_yes']),n(r['both_yes']),n(r['whole_only']),pct(r['linkage'])) for r in d['linkage']]
    headers=[t('Subject screen','Tematski skup'),t('Whole body','Cijeli tekst'),t('Also HNB-local','I uz HNB'),t('Whole only','Samo cijeli tekst'),t('Linkage','Povezanost')]
    options=''.join(f'<option value="{e(kind+":"+term)}">{e(term)} · {t("term","pojam") if kind=="term" else t("phrase","izraz")}</option>' for kind,term in dict.fromkeys((r['kind'],r['term']) for r in d['quarterly']))
    default=[r for r in d['quarterly'] if r['kind']=='term' and r['term']=='banka']
    def qrow(r):
        value=t('Below reporting threshold','Ispod praga prikaza') if r['status']=='below_reporting_threshold' else t('Unavailable','Nedostupno') if r['frequency'] is None else pct(r['frequency'])
        return (r['quarter']+(' *' if r['coverage_state']!='complete' else ''),n(r['count']),n(r['denominator']),value,t('Before 2024','Prije 2024.') if r['regime']=='legacy' else t('From 2024','Od 2024.'))
    return f'''<section class="section" id="jezik"><p class="eyebrow">HNB_MEDIA_LEXICAL_1.1</p><h2>{t('From a subject mention to its HNB context','Od tematskog podudaranja do konteksta HNB-a')}</h2><p class="scope-badge">{t('Fixed edition · distinct bodies · all eligible sources · 2021-01–2026-08 · exploratory, independent validation pending. Main chart filters do not apply here.','Stalno izdanje · različiti tekstovi · svi prihvatljivi izvori · 2021-01–2026-08 · istraživački, neovisna validacija nije dovršena. Filtri glavnog grafikona ne primjenjuju se ovdje.')}</p><p>{t('The same eight patterns are applied to the whole body and to body segments explicitly naming HNB. The local window is contained in the body; titles are excluded from this comparison.','Istih osam obrazaca primjenjuje se na cijeli tekst i na njegove odsječke s izričitim spominjanjem HNB-a. Lokalni prozor dio je tijela teksta; naslovi ne ulaze u ovu usporedbu.')}</p><p><strong>{n(d['pairable_n'])}</strong> {t('pairable bodies out of','usporedivih tekstova od')} {n(d['body_population'])}; {n(d['unavailable_context_n'])} {t('without an eligible local body context','bez prihvatljivog lokalnog konteksta u tijelu')}; {n(d['without_body'])} {t('publications without bodies excluded before deduplication','objava bez tijela izostavljeno prije uklanjanja jednakih tekstova')}.</p><div id="V9"><span class="claim-id">V9 · {t('Whole-body / local linkage','Veza cijelog teksta i lokalnog konteksta')}</span>{table(headers,rows)}<p class="note">{t('Linkage is the share of whole-body matches also found locally, within the same assessable bodies. Screens overlap. A local match does not establish HNB authorship, a main topic, or an explanation of policy.','Povezanost je udio podudaranja u cijelom tekstu koja su prisutna i lokalno, među istim usporedivim tekstovima. Skupovi se preklapaju. Lokalno podudaranje ne dokazuje autorstvo HNB-a, glavnu temu ni objašnjenje politike.')}</p></div><p><a href="data/media/media-subject-linkage.csv">{t('All four cells and coverage · CSV','Sve četiri ćelije i obuhvat · CSV')}</a></p><h3>{t('Selected vocabulary by quarter','Odabrani rječnik po tromjesečjima')}</h3><p>{t('52 terms and 12 phrases from the original dictionary. Each distinct body contributes once per quarter; the explicit-HNB title and body context follow lexical 1.0. The latest complete quarter is 2026 Q2. Partial Q3 covers July–August only. The January 2024 collection change separates the two regimes.','52 pojma i 12 izraza iz izvornog rječnika. Svaki različiti tekst ulazi jednom u tromjesečje; naslov i kontekst tijela s HNB-om slijede leksičku metodu 1.0. Posljednje potpuno tromjesečje jest drugo tromjesečje 2026. Djelomično treće obuhvaća samo srpanj i kolovoz. Promjena prikupljanja u siječnju 2024. odvaja dva režima.')}</p><label hidden data-lexical-js for="lexical-term">{t('Term or phrase','Pojam ili izraz')}<select id="lexical-term">{options}</select></label><p id="lexical-selection" class="view-status">banka · {t('quarterly document presence','tromjesečna prisutnost u tekstovima')}</p>{table([t('Quarter','Tromjesečje'),t('Matching bodies','Podudarni tekstovi'),t('Assessable bodies','Usporedivi tekstovi'),t('Frequency','Učestalost'),t('Collection regime','Režim prikupljanja')],[qrow(r) for r in default],'lexical-quarter-rows')}<p class="note">{t('Positive counts below 30 have no displayed frequency; true zeros remain zero. Denominators below 30 are unavailable. Quarterly body counts cannot be summed to obtain whole-period distinct bodies.','Za pozitivne brojeve manje od 30 ne prikazuje se učestalost; stvarne nule ostaju nule. Nazivnici manji od 30 nisu dostupni za stopu. Tromjesečni brojevi tekstova ne zbrajaju se u broj različitih tekstova cijelog razdoblja.')}</p><p><a href="data/media/media-lexical-quarterly.csv">{t('All quarterly counts and statuses · CSV','Svi tromjesečni brojevi i statusi · CSV')}</a> · <a href="data/media/lexical-extensions.json">{t('Definitions and results · JSON','Definicije i rezultati · JSON')}</a></p><script id="lexical-data" type="application/json">{json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<',chr(92)+'u003c')}</script><script src="lexical.js" defer></script></section>'''
